namespace {

using TiffCraft::Tag;
using TiffCraft::Type;
using TiffCraft::TiffImage;

// Reads the first integer value of an entry without assuming its TIFF type.
bool readFirstValue(const TiffImage::IFD& ifd, Tag tag, std::uint32_t& out) {
  if (!ifd.entries().contains(tag)) {
    return false;
  }
  const auto& entry = ifd.getEntry(tag);
  switch (entry.type()) {
    case Type::SHORT:
      out = entry.values<std::uint16_t>()[0];
      return true;
    case Type::LONG:
      out = entry.values<std::uint32_t>()[0];
      return true;
    default:
      return false;
  }
}
```

