```cpp
std::string allValuesString(const TiffCraft::TiffImage::IFD& ifd, TiffCraft::Tag tag) {
  if (!ifd.entries().contains(tag)) {
    return "n/a";
  }
  const auto& entry = ifd.getEntry(tag);
  std::string result;
  auto append = [&result](std::uint32_t value) {
    if (!result.empty()) { result += ", "; }
    result += std::to_string(value);
  };
  switch (entry.type()) {
    case Type::SHORT:
      for (auto value : entry.values<std::uint16_t>()) { append(value); }
      break;
    case Type::LONG:
      for (auto value : entry.values<std::uint32_t>()) { append(value); }
      break;
    default:
      return "n/a";
  }
  return result.empty() ? "n/a" : result;
}
```

