```cpp
std::string allValuesString(const TiffCraft::TiffImage::IFD& ifd, TiffCraft::Tag tag) {
  if (!ifd.entries().contains(tag)) {
    return "n/a";
  }
  const auto& entry = ifd.getEntry(tag);
  std::string result;
  auto append = [&result](std::uint32_t value) {
    if (!result.empty()) { result += ", "; }
    result += std::to_string(value);
  };
  switch (entry.type()) {
    case Type::SHORT:
      for (auto value : entry.values<std::uint16_t>()) { append(value); }
      break;
    case Type::LONG:
      for (auto value : entry.values<std::uint32_t>()) { append(value); }
      break;
    default:
      return "n/a";
  }
  return result.empty() ? "n/a" : result;
}
```

Total bytes: sum all values of StripByteCounts or TileByteCounts:

```cpp
std::string totalBytesString(const TiffImage::IFD& ifd) {
  const Tag countTag = ifd.entries().contains(Tag::StripByteCounts)
    ? Tag::StripByteCounts
    : (ifd.entries().contains(Tag::TileByteCounts) ? Tag::TileByteCounts : Tag::Null);
  if (countTag == Tag::Null) { return "n/a"; }
  const auto& entry = ifd.getEntry(countTag);
  std::uint64_t total = 0;
  switch (entry.type()) {
    case Type::SHORT:
      for (auto v : entry.values<std::uint16_t>()) total += v;
      break;
    case Type::LONG:
      for (auto v : entry.values<std::uint32_t>()) total += v;
      break;
    default:
      return "n/a";
  }
  return std::to_string(total);
}
```

